9	// 查询结果隔离的公共前置：一份已分出子样、仍有剩余量并已发起交接的原样。
10	// 原样 P：初始 10.000，分出 C1 4.000 后剩余 6.000，交接 TR-1 待确认。
11	func setupPendingParent(t *testing.T) (*Store, time.Time, time.Time) {
12		t.Helper()
13		s, _ := fixedStore(t)
14		mustRegister(t, s, "P", "10.000", "张三", "实验室A")
15		if _, err := s.Split(SplitInput{ParentID: "P", Parts: []SplitPart{
16			{ID: "C1", Qty: "4.000"},
17		}}); err != nil {
18			t.Fatalf("split: %v", err)
