20		hAt := time.Date(2026, 10, 2, 10, 0, 0, 0, time.UTC)
21		if _, err := s.Handover(HandoverInput{
22			TransferID: "TR-1", SampleID: "P",
23			FromHolder: "张三", FromLocation: "实验室A",
24			ToHolder: "李四", ToLocation: "实验室B",
25			HandedOverAt: hAt,
26		}); err != nil {
27			t.Fatalf("handover: %v", err)
28		}
29		return s, hAt, hAt.Add(time.Hour)
30	}
31	
32	// 校验 P 的查询结果仍是真实记录：剩余 6.000、张三在实验室A、子样 [C1]、
33	// 三条历史、待确认交接 TR-1 内容与原交出一致。
34	func requirePristineParent(t *testing.T, got *Sample, hAt time.Time) {
35		t.Helper()
36		if got.Remaining != "6.000" || got.InitialQty != "10.000" {
37			t.Fatalf("数量被改写: init=%s rem=%s", got.InitialQty, got.Remaining)
38		}
39		if got.Holder != "张三" || got.Location != "实验室A" {
40			t.Fatalf("待确认期间持有人/地点应保持交出前状态: %+v", got)
41		}
42		if len(got.Children) != 1 || got.Children[0] != "C1" {
43			t.Fatalf("子样列表被改写: %v", got.Children)
44		}
45		if len(got.History) != 3 {
46			t.Fatalf("历史条数被改写: %d", len(got.History))
47		}
48		wantKinds := []string{"register", "split", "transfer-out"}
49		for i, k := range wantKinds {
50			if got.History[i].Kind != k {
51				t.Fatalf("历史内容被改写: %+v", got.History)
52			}
53		}
54		pt := got.PendingTransfer
55		if pt == nil {
56			t.Fatalf("待确认交接详情丢失")
57		}
58		if pt.TransferID != "TR-1" || pt.ToHolder != "李四" || pt.ToLocation != "实验室B" ||
59			!pt.HandedOverAt.Equal(hAt) || pt.Qty != "6.000" || pt.Confirmed {
60			t.Fatalf("待确认交接详情被改写: %+v", pt)
61		}
62	}
63	
64	func TestGetSampleResultIsIsolatedCopy(t *testing.T) {
65		s, hAt, _ := setupPendingParent(t)
66	
67		got, err := s.GetSample("P")
68		if err != nil {
69			t.Fatal(err)
70		}
71		requirePristineParent(t, got, hAt)
72	
73		// 调用方改写返回结果中的标量、子样编号和历史内容，并增删列表项目。
74		got.Remaining = "0.001"
75		got.InitialQty = "0.001"
76		got.Holder = "王五"
77		got.Location = "仓库Z"
78		got.Children[0] = "C-FAKE"
79		got.Children = append(got.Children, "C-GHOST")
80		got.Children = got.Children[:0]
81		got.History[0].Kind = "destroy"
82		got.History[0].Holder = "王五"
83		got.History[0].Detail = "篡改"
84		got.History = append(got.History, History{Kind: "transfer-in", Holder: "王五"})
85		got.History = got.History[:1]
86		got.PendingTransfer.ToHolder = "王五"
87		got.PendingTransfer.Qty = "0.001"
88	
89		// 再次查询仍应看到原来的真实记录。
90		again, err := s.GetSample("P")
91		if err != nil {
92			t.Fatal(err)
93		}
94		requirePristineParent(t, again, hAt)
95	
96		// 既有子样的来源和数量不受篡改影响。
97		c1, err := s.GetSample("C1")
98		if err != nil {
99			t.Fatal(err)
100		}
101		if c1.ParentID != "P" || c1.InitialQty != "4.000" || c1.Remaining != "4.000" ||
102			c1.Holder != "张三" || c1.Location != "实验室A" {
103			t.Fatalf("子样记录被改写: %+v", c1)
104		}
105		// 篡改中虚构的编号不存在。
106		if _, err := s.GetSample("C-FAKE"); !errors.Is(err, ErrNotFound) {
107			t.Fatalf("虚构子样编号不应存在, got %v", err)
108		}
109		if _, err := s.GetSample("C-GHOST"); !errors.Is(err, ErrNotFound) {
110			t.Fatalf("虚构子样编号不应存在, got %v", err)
111		}
112	}
113	
114	func TestGetSampleResultsAreIndependent(t *testing.T) {
115		s, hAt, _ := setupPendingParent(t)
116	
117		first, err := s.GetSample("P")
118		if err != nil {
119			t.Fatal(err)
120		}
121		second, err := s.GetSample("P")
122		if err != nil {
123			t.Fatal(err)
124		}
125	
126		// 深改第一份结果，第二份已经取得的结果应保持原样。
127		first.Remaining = "0.001"
128		first.Holder = "王五"
129		first.Children[0] = "C-FAKE"
130		first.History[0].Kind = "destroy"
131		first.History[2].Detail = "篡改"
132		first.PendingTransfer.ToHolder = "王五"
133		first.PendingTransfer.Confirmed = true
134	
135		requirePristineParent(t, second, hAt)
136	}
137	
138	func TestPendingTransferViewIsIsolatedCopy(t *testing.T) {
139		s, hAt, rAt := setupPendingParent(t)
140	
141		got, err := s.GetSample("P")
142		if err != nil {
143			t.Fatal(err)
144		}
145		// 改写待确认交接详情：接收人、目的地点、时间、确认标记、数量。
146		pt := got.PendingTransfer
147		pt.ToHolder = "王五"
148		pt.ToLocation = "实验室C"
149		pt.HandedOverAt = hAt.Add(5 * time.Hour)
150		pt.Confirmed = true
151		pt.ConfirmedBy = "王五"
152		pt.Qty = "0.001"
153	
154		// 按交接编号查询的真实交接仍处于待确认，内容与首次交出一致。
155		tr, err := s.GetTransfer("TR-1")
156		if err != nil {
157			t.Fatal(err)
158		}
159		if tr.Confirmed || tr.ToHolder != "李四" || tr.ToLocation != "实验室B" ||
160			!tr.HandedOverAt.Equal(hAt) || tr.Qty != "6.000" || tr.ReceivedAt != nil {
161			t.Fatalf("真实交接被改写: %+v", tr)
162		}
163		// 样品不能因此换人、换地点或解除待确认限制。
164		cur, err := s.GetSample("P")
165		if err != nil {
166			t.Fatal(err)
167		}
168		requirePristineParent(t, cur, hAt)
169	
170		// 按被改写的详情提交确认：另一名接收人、另一个地点均返回 ErrConflict。
171		if _, err := s.Confirm(ConfirmInput{"TR-1", "王五", "实验室B", rAt}); !errors.Is(err, ErrConflict) {
172			t.Fatalf("按篡改接收人确认应 ErrConflict, got %v", err)
173		}
174		if _, err := s.Confirm(ConfirmInput{"TR-1", "李四", "实验室C", rAt}); !errors.Is(err, ErrConflict) {
175			t.Fatalf("按篡改地点确认应 ErrConflict, got %v", err)
176		}
177		// 原交接和原历史保留。
178		tr, _ = s.GetTransfer("TR-1")
179		if tr.Confirmed || tr.ToHolder != "李四" || tr.ToLocation != "实验室B" {
180			t.Fatalf("被拒绝的确认改动了交接: %+v", tr)
181		}
182		cur, _ = s.GetSample("P")
183		requirePristineParent(t, cur, hAt)
184	
185		// 原来指定的接收人在原目的地点、以不早于交出时间的接收时间确认：正常成功。
186		done, err := s.Confirm(ConfirmInput{"TR-1", "李四", "实验室B", rAt})
187		if err != nil {
188			t.Fatalf("确认: %v", err)
189		}
190		if !done.Confirmed || done.Qty != "6.000" {
191			t.Fatalf("确认结果数量应以真实记录为准: %+v", done)
192		}
193		final, err := s.GetSample("P")
194		if err != nil {
195			t.Fatal(err)
196		}
197		if final.Holder != "李四" || final.Location != "实验室B" || final.PendingTransfer != nil {
198			t.Fatalf("确认后持有人/地点/待确认状态错误: %+v", final)
199		}
200		if final.Remaining != "6.000" {
201			t.Fatalf("确认后剩余量应以真实记录为准, got %s", final.Remaining)
202		}
203		// 只追加一次接收历史。
204		if len(final.History) != 4 || final.History[3].Kind != "transfer-in" ||
205			final.History[3].Holder != "李四" || final.History[3].Location != "实验室B" {
206			t.Fatalf("确认后历史错误: %+v", final.History)
207		}
208	}
209	
210	func TestGetSampleNoChildrenNoPendingStaysIsolated(t *testing.T) {
211		s, _ := fixedStore(t)
212		mustRegister(t, s, "S", "2.5", "张三", "实验室A")
213	
214		got, err := s.GetSample("S")
215		if err != nil {
216			t.Fatal(err)
217		}
218		// 无子样、无待确认交接：子样列表为空，历史保留，待确认详情为空。
219		if len(got.Children) != 0 {
220			t.Fatalf("子样列表应为空: %v", got.Children)
221		}
222		if len(got.History) != 1 || got.History[0].Kind != "register" {
223			t.Fatalf("历史应保留: %+v", got.History)
224		}
225		if got.PendingTransfer != nil {
226			t.Fatalf("待确认详情应为空: %+v", got.PendingTransfer)
227		}
228		if got.Remaining != "2.500" || got.InitialQty != "2.500" {
229			t.Fatalf("数量应统一显示三位小数: init=%s rem=%s", got.InitialQty, got.Remaining)
230		}
231	
232		// 调用方在返回结果上自行添入子样或交接详情，不能创建对应记录。
233		got.Children = append(got.Children, "S-CHILD")
234		got.PendingTransfer = &TransferView{TransferID: "TR-GHOST", SampleID: "S", ToHolder: "李四"}
235	
236		again, err := s.GetSample("S")
237		if err != nil {
238			t.Fatal(err)
239		}
240		if len(again.Children) != 0 || again.PendingTransfer != nil {
241			t.Fatalf("自行添入的内容不应进入真实记录: %+v", again)
242		}
243		if len(again.History) != 1 {
244			t.Fatalf("历史不应变化: %+v", again.History)
245		}
246		if _, err := s.GetSample("S-CHILD"); !errors.Is(err, ErrNotFound) {
247			t.Fatalf("添入的子样编号不应被创建, got %v", err)
248		}
249		if _, err := s.GetTransfer("TR-GHOST"); !errors.Is(err, ErrNotFound) {
250			t.Fatalf("添入的交接编号不应被创建, got %v", err)
251		}
252	}
