422			t.Fatalf("重开后销毁信息应保留: %+v", got.Destruction)
423		}
424		if len(got.History) != len(first.History) ||
425			got.History[len(got.History)-1].Kind != "destroy" {
426			t.Fatalf("重开后销毁历史应保留: %+v", got.History)
427		}
